```mermaid
classDiagram
    class Tokenizer {
        +tokenize(expression: str) -> List[Token]
    }
    class Parser {
        +parse(tokens: List[Token]) -> ASTNode
    }
    class Evaluator {
        +evaluate(node: ASTNode) -> Decimal
    }
    class Calculator {
        +evaluate(expression: str) -> str
    }
    class Token {
        -type: TokenType
        -value: str
    }
    class ASTNode {
        <<abstract>>
    }
    class NumberNode {
        -value: Decimal
    }
    class BinaryOpNode {
        -left: ASTNode
        -right: ASTNode
        -operator: str
    }
    Tokenizer ..> Token : creates
    Parser ..> Token : uses
    Parser ..> ASTNode : creates
    Evaluator ..> ASTNode : uses
    Calculator --> Tokenizer
    Calculator --> Parser
    Calculator --> Evaluator
    ASTNode <|-- NumberNode
    ASTNode <|-- BinaryOpNode
```
